INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('39521ae4-ffb9-43ae-b257-192f8330ce80', 'c3c3c3c3-3030-4000-8000-000000000003', 17, 'Dia 17 — Intuição', 'Semana 3: Discernir', '{"pch": "O Esp\u00edrito da verdade vos guiar\u00e1\u2026 Intui\u00e7\u00e3o espiritual \u00e9 o GPS divino.", "verse": "Jo 16,13", "lectio": "Leia Jo 16,12-15. O Esp\u00edrito ensina.", "practice": "Tome uma decis\u00e3o pequena hoje usando apenas intui\u00e7\u00e3o e ora\u00e7\u00e3o.", "question": "Quando sua intui\u00e7\u00e3o te guiou corretamente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;